namespace App\Utils;

use PDO;

class EntityVersion
{
    private static bool $ensured = false;

    public static function ensureTable(PDO $db): void
    {
        if (self::$ensured || $db->inTransaction()) {
            return;
        }

        $db->exec("
            CREATE TABLE IF NOT EXISTS system_entity_versions (
                entity_name VARCHAR(50) PRIMARY KEY,
                version BIGINT UNSIGNED NOT NULL DEFAULT 1,
                updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        ");

        $db->exec("
            INSERT IGNORE INTO system_entity_versions (entity_name, version) VALUES
            ('cash_vault', 1),
            ('categories', 1),
            ('customers', 1),
            ('orders', 1),
            ('partner_settlements', 1),
            ('products', 1),
            ('purchases', 1),
            ('suppliers', 1),
            ('users', 1)
        ");

        self::$ensured = true;
    }

    public static function bump(PDO $db, string ...$entities): void
    {
        if (empty($entities)) {
