        self::ensureTable($db);

        $cleaned = array_values(array_unique(array_filter(array_map('trim', $entities))));
        sort($cleaned);

        if (empty($cleaned)) {
            return;
        }

        $upStmt = $db->prepare("UPDATE system_entity_versions SET version = version + 1 WHERE entity_name = :name");
        $insStmt = $db->prepare("INSERT INTO system_entity_versions (entity_name, version) VALUES (:name, 1) ON DUPLICATE KEY UPDATE version = version + 1");

        foreach ($cleaned as $name) {
            $upStmt->execute(['name' => $name]);
            if ($upStmt->rowCount() === 0) {
                $insStmt->execute(['name' => $name]);
            }
        }
    }

    public static function getAll(PDO $db): array
    {
        self::ensureTable($db);

        $rows = $db->query("SELECT entity_name, version FROM system_entity_versions")->fetchAll(PDO::FETCH_KEY_PAIR);
        if (!$rows) {
            return [
                'orders' => 1,
                'partner_settlements' => 1,
                'cash_vault' => 1,
                'products' => 1,
                'customers' => 1,
                'users' => 1,
            ];
        }

        $result = [];
        foreach ($rows as $k => $v) {
            $result[$k] = (int)$v;
        }
        return $result;
